package greenhouse_ventilation.Greenhouse_Ventilation

import org.sireum._
import art.Art
import greenhouse_ventilation._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Ventilation_Decision_i_control_process_ventilation_decision_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision)
  }

  /** helper function to set the values of all input ports.
   * @param temperature payload for data port temperature
   * @param validity payload for data port validity
   * @param upper_limit payload for data port upper_limit
   */
  def put_concrete_inputs(temperature : Greenhouse_Ventilation.Temperature_Celsius,
                          validity : Greenhouse_Ventilation.Temperature_Validity.Type,
                          upper_limit : Greenhouse_Ventilation.Upper_Temperature_Limit): Unit = {
    put_temperature(temperature)
    put_validity(validity)
    put_upper_limit(upper_limit)
  }


  /** helper function to check Ventilation_Decision_i_control_process_ventilation_decision's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param fan_command method that will be called with the value of the outgoing data
   *        port 'fan_command'.
   * @param sensor_fault method that will be called with the value of the outgoing data
   *        port 'sensor_fault'.
   */
  def check_concrete_output(fan_command: Greenhouse_Ventilation.Fan_Command.Type => B,
                            sensor_fault: Greenhouse_Ventilation.Sensor_Fault_Indication.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val fan_commandValue: Greenhouse_Ventilation.Fan_Command.Type = get_fan_command().get
    if(!fan_command(fan_commandValue)) {
      testFailures = testFailures :+ st"'fan_command' did not match expected: value of the outgoing data port is ${fan_commandValue}"
    }
    val sensor_faultValue: Greenhouse_Ventilation.Sensor_Fault_Indication.Type = get_sensor_fault().get
    if(!sensor_fault(sensor_faultValue)) {
      testFailures = testFailures :+ st"'sensor_fault' did not match expected: value of the outgoing data port is ${sensor_faultValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_temperature(value : Greenhouse_Ventilation.Temperature_Celsius): Unit = {
    Art.insertInInfrastructurePort(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.operational_api.temperature_Id, Greenhouse_Ventilation.Temperature_Celsius_Payload(value))
  }

  // setter for in DataPort
  def put_validity(value : Greenhouse_Ventilation.Temperature_Validity.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.operational_api.validity_Id, Greenhouse_Ventilation.Temperature_Validity_Payload(value))
  }

  // setter for in DataPort
  def put_upper_limit(value : Greenhouse_Ventilation.Upper_Temperature_Limit): Unit = {
    Art.insertInInfrastructurePort(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.operational_api.upper_limit_Id, Greenhouse_Ventilation.Upper_Temperature_Limit_Payload(value))
  }

  // getter for out DataPort
  def get_fan_command(): Option[Greenhouse_Ventilation.Fan_Command.Type] = {
    val value: Option[Greenhouse_Ventilation.Fan_Command.Type] = get_fan_command_payload() match {
      case Some(Greenhouse_Ventilation.Fan_Command_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port fan_command.  Expecting 'Greenhouse_Ventilation.Fan_Command_Payload' but received ${v}")
      case _ => None[Greenhouse_Ventilation.Fan_Command.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_fan_command_payload(): Option[Greenhouse_Ventilation.Fan_Command_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.initialization_api.fan_command_Id).asInstanceOf[Option[Greenhouse_Ventilation.Fan_Command_Payload]]
  }

  // getter for out DataPort
  def get_sensor_fault(): Option[Greenhouse_Ventilation.Sensor_Fault_Indication.Type] = {
    val value: Option[Greenhouse_Ventilation.Sensor_Fault_Indication.Type] = get_sensor_fault_payload() match {
      case Some(Greenhouse_Ventilation.Sensor_Fault_Indication_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port sensor_fault.  Expecting 'Greenhouse_Ventilation.Sensor_Fault_Indication_Payload' but received ${v}")
      case _ => None[Greenhouse_Ventilation.Sensor_Fault_Indication.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_sensor_fault_payload(): Option[Greenhouse_Ventilation.Sensor_Fault_Indication_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.initialization_api.sensor_fault_Id).asInstanceOf[Option[Greenhouse_Ventilation.Sensor_Fault_Indication_Payload]]
  }

}
